<div class="grid gap-5 xl:grid-cols-[1fr_340px]"><article class="rounded-xl border bg-card p-6 md:p-10"><p class="text-xs font-semibold uppercase tracking-widest text-orange-500">Draft surat</p><h2 class="mt-2 font-serif text-2xl font-semibold">{row.subject}</h2><div class="mt-7 whitespace-pre-wrap border-t pt-7 font-serif text-[17px] leading-8 text-black-500">{row.body}</div></article><aside class="space-y-5"><section class="rounded-xl border bg-card p-5"><h2 class="font-serif text-lg font-semibold">Informasi</h2><dl class="mt-4 grid gap-3 text-sm"><div><dt class="text-muted-foreground">Deadline</dt><dd>{formatDate(row.deadline,true)}</dd></div><div><dt class="text-muted-foreground">Pengaju</dt><dd>{row.submitter?.name||'—'}</dd></div><div><dt class="text-muted-foreground">PJ</dt><dd>{row.assigned_pj?.name||'Belum ditetapkan'}</dd></div><div><dt class="text-muted-foreground">Diajukan</dt><dd>{formatDate(row.created_at,true)}</dd></div></dl></section>
